# Operator-run migration: delete LMF (Leachate Mixing Fraction).
#
# Robin's instruction (2026-10-16): LMF is a DERIVED quantity computed by a
# different package (the analyte's own comment: "Generated by `add_LB_ratio()`")
# and does not belong in the monitoring database.
#
# What goes, in FK order (children first):
#   * 2,267 `analysis` rows (1,840 with a value, 427 NULL) - one per sample, all
#     on lab_method 00000000-0000-0000-0000-000000000003
#     (`Computed: Leachate Mixing Fraction`, organisation NULL);
#   * that `lab_method` row;
#   * the 4 `guideline` rows (`Leachate Signature Index` thresholds 6/10/14/18)
#     and the 1 `analyte_mask` row (`long` = "Leachate Signature Index") that hang
#     off the analyte. NOT in the original instruction - but both carry a FOREIGN
#     KEY to `analyte`, so the analyte cannot be deleted while they exist, and
#     they describe only this analyte. Backed up like the rest.
#   * the `analyte` row c316aea7-69e5-4723-9624-0d4cdee8fe6d (`LMF`).
#
# SAMPLES ARE NOT DELETED. The convention is that samples are never removed as a
# side effect; this migration only REPORTS (logs, not gates) how many samples are
# left with no analysis.
#
# `guideline` is not in the mutation-layer allowlist, so its rows are deleted
# with plain SQL and a hand-written `change_log` row each (action = delete, tbl
# = guideline), the same shape `db_delete()` writes.
#
# BACKUP OF THE ROWS: before anything is written, every deleted row is dumped to
# `011-delete-lmf-BACKUP-<table>.csv` beside this file (analysis, lab_method,
# analyte, analyte_mask, guideline), IN ADDITION to the whole-file duckdb backup
# in `snapshot_dir`. The CSVs are the in-tree record; restoring from them is
# manual (INSERT in reverse FK order).
#
# Marker 1011 in `schema_version`. Idempotent: with the marker present the
# migration re-verifies that no LMF row remains and does nothing.
#
#   devtools::load_all(".")
#   env <- new.env()
#   sys.source("dev/migrations/011-delete-lmf.R", envir = env)
#   env$mig011_run(db = st_config("live_db"),
#                  snapshot_dir = st_config("snapshot_dir"), dry_run = TRUE)

.mig011_marker_version <- 1011L
.mig011_actor <- "011-delete-lmf"
.mig011_analyte <- "c316aea7-69e5-4723-9624-0d4cdee8fe6d"
.mig011_lab <- "00000000-0000-0000-0000-000000000003"
.mig011_lab_name <- "Computed: Leachate Mixing Fraction"
.mig011_reason <- "011: LMF (leachate mixing fraction) is a derived quantity computed by a different package and does not belong in this database (Robin, 2026-10-16)"

.mig011_default <- function(x, default) if (is.null(x)) default else x

.mig011_scalar <- function(con, sql, ...) {
  as.integer(DBI::dbGetQuery(con, sql, params = list(...))[[1]][[1]])
}

.mig011_state <- function(con) {
  list(
    analysis_lmf   = .mig011_scalar(con, "SELECT COUNT(*) FROM analysis WHERE uuid_lab = ?", .mig011_lab),
    lab_method_lmf = .mig011_scalar(con, "SELECT COUNT(*) FROM lab_method WHERE uuid = ?", .mig011_lab),
    analyte_lmf    = .mig011_scalar(con, "SELECT COUNT(*) FROM analyte WHERE uuid = ?", .mig011_analyte),
    mask_lmf       = .mig011_scalar(con, "SELECT COUNT(*) FROM analyte_mask WHERE uuid_analyte = ?", .mig011_analyte),
    guideline_lmf  = .mig011_scalar(con, "SELECT COUNT(*) FROM guideline WHERE uuid_analyte = ?", .mig011_analyte)
  )
}

.mig011_counts <- function(con) {
  list(
    analysis = .mig011_scalar(con, "SELECT COUNT(*) FROM analysis"),
    analyte = .mig011_scalar(con, "SELECT COUNT(*) FROM analyte"),
    lab_method = .mig011_scalar(con, "SELECT COUNT(*) FROM lab_method"),
    analyte_mask = .mig011_scalar(con, "SELECT COUNT(*) FROM analyte_mask"),
    guideline = .mig011_scalar(con, "SELECT COUNT(*) FROM guideline"),
    sample = .mig011_scalar(con, "SELECT COUNT(*) FROM \"sample\""),
    change_log = .mig011_scalar(con, "SELECT COUNT(*) FROM change_log")
  )
}

# Samples that would have NO analysis once the LMF rows are gone.
.mig011_orphans <- function(con) {
  .mig011_scalar(con,
    "SELECT COUNT(*) FROM \"sample\" s WHERE NOT EXISTS
       (SELECT 1 FROM analysis a WHERE a.uuid_sample = s.uuid AND a.uuid_lab <> ?)",
    .mig011_lab)
}

.mig011_check_preconditions <- function(con) {
  fail <- function(msg) cli::cli_abort(paste0("011-delete-lmf: ", msg),
                                       class = "sampletidy_error")
  a <- DBI::dbGetQuery(con, "SELECT name FROM analyte WHERE uuid = ?",
                       params = list(.mig011_analyte))
  if (nrow(a) != 1L || !identical(a$name[[1]], "LMF")) {
    fail("analyte c316aea7... is not exactly one row named 'LMF'; the registry moved since the instruction.")
  }
  lm <- DBI::dbGetQuery(con, "SELECT name, uuid_analyte, organisation FROM lab_method WHERE uuid = ?",
                        params = list(.mig011_lab))
  if (nrow(lm) != 1L || !identical(lm$name[[1]], .mig011_lab_name) ||
      !identical(lm$uuid_analyte[[1]], .mig011_analyte) || !is.na(lm$organisation[[1]])) {
    fail("lab_method 00000000-...-0003 is not exactly `Computed: Leachate Mixing Fraction` (organisation NULL) on the LMF analyte.")
  }
  other <- .mig011_scalar(con,
    "SELECT COUNT(*) FROM lab_method WHERE uuid_analyte = ? AND uuid <> ?",
    .mig011_analyte, .mig011_lab)
  if (other != 0L) fail("the LMF analyte has another lab_method; refusing to guess whether it should go too.")
  # Nothing but the LMF method's analyses may be on the method, and the LMF
  # analyses must all be on it (they are, by construction: analysis -> lab_method).
  invisible(TRUE)
}

.mig011_verify <- function(con) {
  st <- .mig011_state(con)
  if (any(unlist(st) != 0L)) {
    bad <- paste(names(st)[unlist(st) != 0L], collapse = ", ")
    cli::cli_abort("011-delete-lmf verify failed: LMF rows remain in {bad}.",
                   class = "sampletidy_error")
  }
  invisible(TRUE)
}

.mig011_backup_csvs <- function(con, dir) {
  dumps <- list(
    analysis     = list("SELECT * FROM analysis WHERE uuid_lab = ? ORDER BY uuid", .mig011_lab),
    lab_method   = list("SELECT * FROM lab_method WHERE uuid = ?", .mig011_lab),
    analyte      = list("SELECT * FROM analyte WHERE uuid = ?", .mig011_analyte),
    analyte_mask = list("SELECT * FROM analyte_mask WHERE uuid_analyte = ?", .mig011_analyte),
    guideline    = list("SELECT * FROM guideline WHERE uuid_analyte = ? ORDER BY level", .mig011_analyte)
  )
  out <- character()
  for (nm in names(dumps)) {
    df <- DBI::dbGetQuery(con, dumps[[nm]][[1]], params = list(dumps[[nm]][[2]]))
    path <- file.path(dir, sprintf("011-delete-lmf-BACKUP-%s.csv", nm))
    if (nrow(df) == 0L && file.exists(path)) next   # resumed run: keep the real backup
    utils::write.csv(df, path, row.names = FALSE, na = "", fileEncoding = "UTF-8")
    back <- utils::read.csv(path, stringsAsFactors = FALSE, na.strings = "", encoding = "UTF-8")
    if (nrow(back) != nrow(df)) {
      cli::cli_abort("011-delete-lmf: CSV backup of {nm} did not round-trip ({nrow(back)} vs {nrow(df)} rows).",
                     class = "sampletidy_error")
    }
    out[[nm]] <- path
  }
  out
}

mig011_backup <- function(db, snapshot_dir, .now = NULL) {
  now <- .mig011_default(.now, Sys.time())
  ts <- format(now, "%Y%m%dT%H%M%OS3", tz = "UTC")
  dest <- file.path(snapshot_dir, sprintf("monitoring_pre-011-delete-lmf_%sZ.duckdb", ts))
  live_counts <- with_db_write(function(con) {
    DBI::dbExecute(con, "CHECKPOINT")
    counts <- .mig011_counts(con)
    ok <- tryCatch(suppressWarnings(file.copy(db, dest, overwrite = FALSE)),
                   error = function(e) FALSE)
    if (!isTRUE(ok)) {
      cli::cli_abort("{db}: failed to write backup copy to {dest}.", class = "sampletidy_error")
    }
    counts
  }, db = db)
  verify_con <- tryCatch(DBI::dbConnect(duckdb::duckdb(), dest, read_only = TRUE),
                         error = function(e) NULL)
  if (is.null(verify_con)) {
    cli::cli_abort("{db}: backup verification failed - cannot open {dest}.", class = "sampletidy_error")
  }
  on.exit(DBI::dbDisconnect(verify_con, shutdown = TRUE), add = TRUE)
  if (!identical(live_counts, .mig011_counts(verify_con))) {
    cli::cli_abort("{db}: backup verification failed - counts differ from {dest}.", class = "sampletidy_error")
  }
  dest
}

mig011_run <- function(db, snapshot_dir, dry_run = FALSE, .now = NULL,
                       csv_dir = NULL) {
  logf <- function(fmt, ...) cat(sprintf("[%s] %s\n", db, sprintf(fmt, ...)))
  if (is.null(csv_dir)) {
    csv_dir <- if (dir.exists("dev/migrations")) "dev/migrations" else snapshot_dir
  }

  # ---- Step 0: marker ----
  marker_con <- st_connect(db, read_only = TRUE)
  mine <- tryCatch(
    DBI::dbGetQuery(marker_con,
      "SELECT version, applied_at FROM schema_version WHERE version = ?",
      params = list(.mig011_marker_version)),
    finally = DBI::dbDisconnect(marker_con, shutdown = TRUE))
  if (nrow(mine) > 0) {
    check_con <- st_connect(db, read_only = TRUE)
    tryCatch(.mig011_verify(check_con), finally = DBI::dbDisconnect(check_con, shutdown = TRUE))
    logf("011-delete-lmf already applied at %s; no LMF row remains; nothing to do.",
         format(mine$applied_at[[1]]))
    return(invisible(list(status = "already_migrated", backup_path = NA_character_,
                          restore_command = NA_character_, recorded_at = mine$applied_at[[1]])))
  }

  # ---- Step 1: preconditions, read-only, BEFORE the backup ----
  pre_con <- st_connect(db, read_only = TRUE)
  pre <- tryCatch({
    .mig011_check_preconditions(pre_con)
    list(state = .mig011_state(pre_con), orphans = .mig011_orphans(pre_con))
  }, finally = DBI::dbDisconnect(pre_con, shutdown = TRUE))
  logf("To delete: %d analysis, %d lab_method, %d analyte, %d analyte_mask, %d guideline. Samples left with no analysis (NOT deleted): %d.",
       pre$state$analysis_lmf, pre$state$lab_method_lmf, pre$state$analyte_lmf,
       pre$state$mask_lmf, pre$state$guideline_lmf, pre$orphans)

  if (isTRUE(dry_run)) {
    logf("DRY RUN: every precondition passed. No backup taken, nothing written.")
    return(invisible(list(status = "dry_run", backup_path = NA_character_,
                          restore_command = NA_character_, recorded_at = NA)))
  }

  # ---- Step 2: row dump (CSV) and verified whole-file backup ----
  csv_paths <- with_db_write(function(con) .mig011_backup_csvs(con, csv_dir), db = db)
  logf("Row backups written: %s", paste(basename(csv_paths), collapse = ", "))
  backup_path <- mig011_backup(db = db, snapshot_dir = snapshot_dir, .now = .now)
  restore_command <- sprintf("cp %s %s", shQuote(backup_path), shQuote(db))
  logf("Backup verified: %s", backup_path)
  logf("To restore if needed: %s", restore_command)

  recorded_at <- .mig011_default(.now, Sys.time())

  with_db_write(function(con) {
    before <- .mig011_counts(con)
    # THREE TRANSACTIONS, NOT ONE. DuckDB cannot delete a parent row in the same
    # transaction that deleted its children (its FK check still sees the child
    # index entries: "key is still referenced by a foreign key in a different
    # table"). So: (1) the analyses; (2) the lab_method, guideline and
    # mask rows; (3) the analyte plus the marker. If a later one fails the earlier
    # ones stay committed and a re-run is safe: preconditions still hold, there are
    # simply no analyses left, and the CSV dump never overwrites a non-empty
    # backup with an empty one.
    db_transaction(con, function(con) {
      uuids <- DBI::dbGetQuery(con, "SELECT uuid FROM analysis WHERE uuid_lab = ? ORDER BY uuid",
                               params = list(.mig011_lab))$uuid
      for (u in uuids) db_delete(con, "analysis", uuid = u, actor = .mig011_actor, reason = .mig011_reason)
      NULL
    })
    db_transaction(con, function(con) {
      db_delete(con, "lab_method", uuid = .mig011_lab, actor = .mig011_actor, reason = .mig011_reason)

      # guideline is not in the mutation allowlist: plain SQL + the change_log
      # row db_delete() would have written.
      gl <- DBI::dbGetQuery(con, "SELECT uuid FROM guideline WHERE uuid_analyte = ? ORDER BY uuid",
                            params = list(.mig011_analyte))$uuid
      for (g in gl) {
        n <- DBI::dbExecute(con, "DELETE FROM guideline WHERE uuid = ?", params = list(g))
        stopifnot(n == 1L)
        .st_write_change_log(con, at = Sys.time(), actor = .mig011_actor, action = "delete",
                             tbl = "guideline", uuid_row = g, field = NA_character_,
                             old = g, new = NA_character_,
                             reason = paste0(.mig011_reason, " (guideline row hangs off the LMF analyte by FK)"),
                             source_hash = NA_character_)
      }

      db_delete(con, "analyte_mask", key = list(uuid_analyte = .mig011_analyte, variant = "long"),
                actor = .mig011_actor, reason = .mig011_reason)
      NULL
    })
    db_transaction(con, function(con) {
      db_delete(con, "analyte", uuid = .mig011_analyte, actor = .mig011_actor, reason = .mig011_reason)

      DBI::dbExecute(con, "INSERT INTO schema_version (version, applied_at) VALUES (?, ?)",
                     params = list(.mig011_marker_version, recorded_at))

      .mig011_verify(con)
      after <- .mig011_counts(con)
      expect <- before
      expect$analysis <- before$analysis - pre$state$analysis_lmf
      expect$lab_method <- before$lab_method - 1L
      expect$analyte <- before$analyte - 1L
      expect$analyte_mask <- before$analyte_mask - pre$state$mask_lmf
      expect$guideline <- before$guideline - pre$state$guideline_lmf
      expect$change_log <- before$change_log + pre$state$analysis_lmf + 1L + pre$state$guideline_lmf +
        pre$state$mask_lmf + 1L
      if (!identical(after, expect)) {
        cli::cli_abort("011-delete-lmf verify failed: table counts after are not before minus exactly the LMF rows (samples must be unchanged).",
                       class = "sampletidy_error")
      }
      NULL
    })
    logf("Verify passed: LMF removed; samples untouched.")
    invisible(TRUE)
  }, db = db)

  logf("011-delete-lmf migrated successfully.")
  invisible(list(status = "migrated", backup_path = backup_path,
                 restore_command = restore_command, recorded_at = recorded_at))
}
